using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;class Inventory{static IEnumerable<TypeDefinition> Walk(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in Walk(n))yield return x;}static void Main(string[]a){using(var m=ModuleDefinition.ReadModule(a[0]))foreach(var t in m.Types.SelectMany(Walk))foreach(var v in t.Methods.Where(x=>x.HasBody))foreach(var i in v.Body.Instructions)if(i.Operand is MethodReference r&&(r.Name=="ApplyEffectForms"||r.Name=="ApplyMagicEffect"||r.Name=="ApplyEffectOnCharacter"||r.Name=="ApplyEffectOnPosition"||r.Name=="RollMagicalHitPointsPool"||r.Name=="RollHitDie")){Console.WriteLine(v.FullName+" @"+i.Offset.ToString("X4")+" -> "+r.FullName);}}}